mapper.select:
select distinct a.TRANSACTIONID,a.EXAMINETYPE,a.TOTALSCORE,a.FIRSTID,b.EXAMINEEMPHASIS,b.SERIALNUMBER,b.EMPLOYMENTOBJECTIVE,max(a.id) as max
from tbl_fwgl_examine_topic_second a
left join tbl_fwgl_examine_topic_first b on a.FIRSTID = b.ID
where 1=1





    and a.BELONGGROUP = #{param.belongGroup}


    and a.CREATOR = #{param.creator}


    and a.WORKUNIT = #{param.workUnit}

group by a.TRANSACTIONID,a.TRANSACTIONID,a.EXAMINETYPE,a.TOTALSCORE,a.FIRSTID,b.EXAMINEEMPHASIS,b.SERIALNUMBER,b.EMPLOYMENTOBJECTIVE
order by max desc
